def execute(self, *args, **kwargs):
        while True:
            try:
                if self._conn is None or self._conn.closed:
                    self._conn = self.engine.connect()
                    if self._timeout > 0:
                        # only log reconnections when we keep the connection alive between requests otherwise we'll spam
                        # the log
                        if self._conn is None:
                            self._logger.info(
                                "Reconnecting to DB; connection not existing."
                            )
                        else:
                            self._logger.info("Reconnecting to DB; connection closed.")
                        if self._watchdog is not None:
                            # in case connection is dead, but watchdog is still up, something else killed the connection,
                            # make the watchdog quit, then making a new one
                            self._watchdog.kill()
                        self._watchdog = ConnectionWatchDog(
                            self._conn, self._lock, timeout=self._timeout
                        )
                        self._watchdog.start()
                if self._timeout > 0:
                    self._watchdog.kick()
                with self._lock:
                    result = self._conn.execute(*args, **kwargs)
                    break
            except OperationalError as e:
                print(
                    f"Database connection failed with operational error {e}, waiting 5s, then re-trying."
                )
                time.sleep(5)
        return result

def deferred_init(self) -> None:
        all_vols = self.asrv.vfs.all_vols
        have_e2d = self.init_indexes(all_vols, [], False)

        if self.stop:
            # up-mt consistency not guaranteed if init is interrupted;
            # drop caches for a full scan on next boot
            self._drop_caches()

            if self.pp:
                self.pp.end = True
                self.pp = None

            return

        if not self.pp and self.args.exit == "idx":
            return self.hub.sigterm()

        Daemon(self._snapshot, "up2k-snapshot")
        if have_e2d:
            Daemon(self._hasher, "up2k-hasher")
            Daemon(self._sched_rescan, "up2k-rescan")
            if self.mtag:
                for n in range(max(1, self.args.mtag_mt)):
                    Daemon(self._tagger, "tagger-{}".format(n))

                Daemon(self._run_all_mtp, "up2k-mtp-init")

