async def cpu_profile(
        self, pid: int, format="flamegraph", duration: float = 5, native: bool = False
    ) -> (bool, str):
        pyspy = shutil.which("py-spy")
        if pyspy is None:
            return False, "py-spy is not installed"

        if format not in ("flamegraph", "raw", "speedscope"):
            return (
                False,
                f"Invalid format {format}, " + "must be [flamegraph, raw, speedscope]",
            )

        if format == "flamegraph":
            extension = "svg"
        else:
            extension = "txt"
        profile_file_path = (
            self.profile_dir_path / f"{format}_{pid}_cpu_profiling.{extension}"
        )
        cmd = [
            pyspy,
            "record",
            "-o",
            profile_file_path,
            "-p",
            str(pid),
            "-d",
            str(duration),
            "-f",
            format,
        ]
        if sys.platform == "linux" and native:
            cmd.append("--native")
        if await _can_passwordless_sudo():
            cmd = ["sudo", "-n"] + cmd
        process = await asyncio.create_subprocess_exec(
            *cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
        stdout, stderr = await process.communicate()
        if process.returncode != 0:
            return False, _format_failed_pyspy_command(cmd, stdout, stderr)
        else:
            return True, open(profile_file_path, "rb").read()

async def trace_dump(self, pid: int, native: bool = False) -> (bool, str):
        pyspy = shutil.which("py-spy")
        if pyspy is None:
            return False, "py-spy is not installed"

        cmd = [pyspy, "dump", "-p", str(pid)]
        # We
        if sys.platform == "linux" and native:
            cmd.append("--native")
        if await _can_passwordless_sudo():
            cmd = ["sudo", "-n"] + cmd
        process = await asyncio.create_subprocess_exec(
            *cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
        stdout, stderr = await process.communicate()
        if process.returncode != 0:
            return False, _format_failed_pyspy_command(cmd, stdout, stderr)
        else:
            return True, stdout.decode("utf-8")

def c2p(mml, simple=False):
    """Transforms a document in MathML content (like the one that sympy produces)
    in one document in MathML presentation, more suitable for printing, and more
    widely accepted

    Examples
    ========

    >>> from sympy.utilities.mathml import c2p
    >>> mml = '<apply> <exp/> <cn>2</cn> </apply>'
    >>> c2p(mml,simple=True) != c2p(mml,simple=False)
    True

    """

    if not mml.startswith('<math'):
        mml = add_mathml_headers(mml)

    if simple:
        return apply_xsl(mml, 'mathml/data/simple_mmlctop.xsl')

    return apply_xsl(mml, 'mathml/data/mmlctop.xsl')

def __del__(self):
        """Ensure all threads have been joined for cleanup."""
        try:
            # it's possible the global state is not well defined, so just in
            # case we'll wrap it all up in a try/except
            self._terminated = True
            if self._n_workers > 0:
                LOGGER.debug("shutting down workers")
                self._worker_pool.close()
                self._worker_pool.terminate()
                # close down the log monitor thread
                self._logging_queue.put(None)
                timedout = not self._logging_monitor_thread.join(_MAX_TIMEOUT)
                if timedout:
                    LOGGER.debug(
                        '_logging_monitor_thread %s timed out',
                        self._logging_monitor_thread)

            if self._logging_queue:
                # Close down the logging monitor thread.
                self._logging_queue.put(None)
                self._logging_monitor_thread.join(_MAX_TIMEOUT)
                # drain the queue if anything is left
                while True:
                    try:
                        x = self._logging_queue.get_nowait()
                        LOGGER.debug(
                            "the logging queue had this in it: %s", x)
                    except queue.Empty:
                        break

            self._taskgraph_started_event.set()
            if self._n_workers >= 0:
                self._executor_ready_event.set()
                for executor_thread in self._task_executor_thread_list:
                    try:
                        executor_thread.join(_MAX_TIMEOUT)
                        timedout = executor_thread.is_alive()
                        if timedout:
                            LOGGER.debug(
                                'task executor thread timed out %s',
                                executor_thread)
                    except Exception:
                        LOGGER.exception(
                            "Exception when joining %s", executor_thread)
                if self._reporting_interval is not None:
                    LOGGER.debug("joining _monitor_thread.")
                    if self._logging_queue:
                        self._logging_queue.put(None)
                    self._execution_monitor_wait_event.set()
                    self._execution_monitor_thread.join(_MAX_TIMEOUT)
                    timedout = self._execution_monitor_thread.is_alive()
                    if timedout:
                        LOGGER.debug(
                            '_monitor_thread %s timed out',
                            self._execution_monitor_thread)
                    for task in self._task_hash_map.values():
                        # this is a shortcut to get the tasks to mark as joined
                        task.task_done_executing_event.set()

            # drain the task ready queue if there's anything left
            while True:
                try:
                    x = self._task_ready_priority_queue.get_nowait()
                    LOGGER.debug(
                        "task_ready_priority_queue not empty contains: %s", x)
                except queue.Empty:
                    break
            LOGGER.debug('taskgraph terminated')
        except Exception:
            LOGGER.exception('exception occurred during __del__')

def get_open_files(self):
        retlist = []
        files = os.listdir("/proc/%s/fd" % self.pid)
        hit_enoent = False
        for fd in files:
            file = "/proc/%s/fd/%s" % (self.pid, fd)
            if os.path.islink(file):
                try:
                    file = os.readlink(file)
                except OSError:
                    # ENOENT == file which is gone in the meantime
                    err = sys.exc_info()[1]
                    if err.errno == errno.ENOENT:
                        hit_enoent = True
                        continue
                    raise
                else:
                    # If file is not an absolute path there's no way
                    # to tell whether it's a regular file or not,
                    # so we skip it. A regular file is always supposed
                    # to be absolutized though.
                    if file.startswith('/') and os.path.isfile(file):
                        ntuple = nt_openfile(file, int(fd))
                        retlist.append(ntuple)
        if hit_enoent:
            # raise NSP if the process disappeared on us
            os.stat('/proc/%s' % self.pid)
        return retlist

def get_metric_variables(self) -> List[Any]:
    """Returns a list containing the metric variable values."""
