                    "200 OK",
                    headers=headers)

def set_name(self,name):
        """
        All objects have names, and with the exception of System
        they aren't picky about it.
        """
        if self.name not in ["",None] and self.parent not in ["",None] and self.name == self.parent:
            raise CX(_("self parentage is weird"))
        if not isinstance(name, basestring):
            raise CX(_("name must be a string"))
        for x in name:
            if not x.isalnum() and not x in [ "_", "-", ".", ":", "+" ] :
                raise CX(_("invalid characters in name: '%s'" % name)) 
        self.name = name
        return True

def gen_urlgrab_ssl_opts(self, yumopts):
        # use SSL options if specified in yum opts
        urlgrab_ssl_opts = {}
        if 'sslclientkey' in yumopts:
            urlgrab_ssl_opts["ssl_key"] = yumopts['sslclientkey']
        if 'sslclientcert' in yumopts:
            urlgrab_ssl_opts["ssl_cert"] = yumopts['sslclientcert']
        if 'sslcacert' in yumopts:
            urlgrab_ssl_opts["ssl_ca_cert"] = yumopts['sslcacert']
        # note that the default of urlgrabber is to verify the peer and host
        # but the default here is NOT to verify them unless sslverify is
        # explicitly set to 1 in yumopts
        if 'sslverify' in yumopts:
            if yumopts['sslverify'] == 1:
                urlgrab_ssl_opts["ssl_verify_peer"] = True
                urlgrab_ssl_opts["ssl_verify_host"] = True
            else:
                urlgrab_ssl_opts["ssl_verify_peer"] = False
                urlgrab_ssl_opts["ssl_verify_host"] = False

        return urlgrab_ssl_opts

def __find_compare(self, from_search, from_obj):

        if isinstance(from_obj, basestring):
            # FIXME: fnmatch is only used for string to string comparisions
            # which should cover most major usage, if not, this deserves fixing
            if fnmatch.fnmatch(from_obj.lower(), from_search.lower()):
                return True
            else:
                return False    

        else:
            if isinstance(from_search, basestring):
                if type(from_obj) == type([]):
                    from_search = utils.input_string_or_list(from_search)
                    for x in from_search:
                        if x not in from_obj:
                            return False
                    return True            

                if type(from_obj) == type({}):
                    (junk, from_search) = utils.input_string_or_hash(from_search,allow_multiples=True)
                    for x in from_search.keys():
                        y = from_search[x]
                        if not from_obj.has_key(x):
                            return False
                        if not (y == from_obj[x]):
                            return False
                    return True

                if type(from_obj) == type(True):
                    if from_search.lower() in [ "true", "1", "y", "yes" ]:
                        inp = True
                    else:
                        inp = False
                    if inp == from_obj:
                        return True
                    return False

            raise CX(_("find cannot compare type: %s") % type(from_obj))

