        try:
            Site.objects.get(pk=settings.SITE_ID)
        except (OperationalError, ProgrammingError):
            # Redirect to Setup view
            return HttpResponseRedirect(reverse("init-db"))
        return None

def parse_font(value):
    ret = {"font-family": "", "font-size": "", "font-style": "normal",
           "font-variant": "normal", "font-weight": "normal",
           "line-height": "normal"}

    font_styles = ["italic", "oblique"]
    font_variants = ["small-caps"]
    font_weights = ["bold", "bolder", "lighter", "100", "200", "300", "400",
                    "500", "600", "700", "800", "900"]

    for element in value.split():
        if element == "normal":
            continue
        elif ret["font-family"]:
            ret["font-family"] += " " + element
        elif element in font_styles:
            ret["font-style"] = element
        elif element in font_variants:
            ret["font-variant"] = element
        elif element in font_weights:
            ret["font-weight"] = element
        else:
            if not ret["font-size"]:
                parts = element.split("/")
                ret["font-size"] = parts[0]
                if len(parts) > 1:
                    ret["line-height"] = parts[1]
                continue
            else:
                ret["font-family"] = element

    return ret

def process_request(self, request):
        if request.user:
            request.user = SimpleLazyObject(partial(self._verify_user, request, request.user))
        user = request.user
        if self._require_verified_user(request):
            user_has_device = django_otp.user_has_device(user, confirmed=True)

            if user_has_device and not user.is_verified():
                return redirect_to_login(
                    request.get_full_path(), login_url=reverse("wagtail_2fa_auth")
                )

            elif not user_has_device and settings.WAGTAIL_2FA_REQUIRED:
                # only allow the user to visit the admin index page and the
                # admin setup page
                return redirect_to_login(
                    request.get_full_path(), login_url=reverse("wagtail_2fa_device_new")
                )

def __call__(self, request):
        if hasattr(self, 'process_request'):
            response = self.process_request(request)
        if not response:
            response = self.get_response(request)
        if hasattr(self, 'process_response'):
            response = self.process_response(request, response)
        return response

def _resolve(self, request_id, result):
        method, okey, seq = request_id
        self._results[request_id] = result
        if okey not in self._sequences:
            raise RuntimeError('unknown ordering key')
        while len(self._sequences[okey]) > 0:
            s = self._sequences[okey][0]
            rid = (s.method, okey, s.seq)
            if rid in self._results:
                heapq.heappop(self._sequences[okey])
                result = self._results.pop(rid, None)
                fut = self._futures.pop(rid, None)
                _resolve_future(rid, fut, result, self._log)
            else:
                break
        if len(self._sequences[okey]) == 0:
            del self._sequences[okey]

async def __aexit__(self, *exc_info) -> None:
        if self._send_task is not None:
            await self._outgoing_queue.put(CLOSED)
            await self._send_task
        if self._recv_task is not None:
            # TODO: pass exception description, e.g. during invoke timeout
            if self._opener is not None:
                await self._opener.__aexit__(*exc_info)
            self._recv_task.cancel()
            await self._recv_task
        if self._scheduler is not None:
            await self._scheduler.close()
        if self._transport is not None:
            await self._transport.close()

async def _send_loop(self) -> None:
        '''
        Fetches and sends out the completed task responses.
        '''
        if self._connection is None:
            raise RuntimeError('consumer is not opened yet.')
        while True:
            try:
                msg = await self._outgoing_queue.get()
                if msg is CLOSED:
                    break
                assert not isinstance(msg, Sentinel)
                await self._connection.send_message(
                    msg.encode(self._serializer))
            except asyncio.CancelledError:
                break
            except Exception:
                log.exception('unexpected error')

def decode(cls, buffer: bytes) -> Any:
        if not buffer:
            return None
        return cls(*munpackb(buffer))

def resolve(self, request_id, result):
        fut = self._futures.pop(request_id, None)
        _resolve_future(request_id, fut, result, self._log)

def lc_attributes(self) -> Dict[str, Any]:
        return {
            "template_format": self.template_format,
        }

def __await_reply(self, pr, rsocks, wsocks, timeout):
        extra = 0
        read_buffers = {}
        while (timeout + extra) > time.time():
            if not wsocks and not rsocks:
                break

            r, w, x = select.select(rsocks, wsocks, rsocks + wsocks,
                                    (timeout + extra) - time.time())
            for sock in x:
                sock.close()
                try:
                    rsocks.remove(sock)
                except ValueError:
                    pass
                try:
                    wsocks.remove(sock)
                except ValueError:
                    pass

            for sock in w:
                try:
                    if self.sock_type(sock) == socket.SOCK_DGRAM:
                        # If we proxy over UDP, remove the 4-byte length
                        # prefix since it is TCP only.
                        sock.sendall(pr.request[4:])
                    else:
                        sock.sendall(pr.request)
                        extra = 10  # New connections get 10 extra seconds
                except Exception:
                    logging.exception('Error in recv() of %s', sock)
                    continue
                rsocks.append(sock)
                wsocks.remove(sock)

            for sock in r:
                try:
                    reply = self.__handle_recv(sock, read_buffers)
                except Exception:
                    logging.exception('Error in recv() of %s', sock)
                    if self.sock_type(sock) == socket.SOCK_STREAM:
                        # Remove broken TCP socket from readers
                        rsocks.remove(sock)
                else:
                    if reply is not None:
                        return reply

        return None

def can_decrypt(self):
        """Legacy function to check if you can call :meth:`decrypt`.

        .. deprecated:: 3.0"""
        return self._key.can_decrypt()

def can_encrypt(self):
        """Legacy function to check if you can call :meth:`encrypt`.

        .. deprecated:: 3.0"""
        return self._key.can_encrypt()

def can_decrypt(self):
        """Return True if this cipher object can be used for decryption."""
        return self._key.can_decrypt()

def parse_lheading(self, m):
        """Parse setext heading."""
        self.tokens.append({
            'type': 'heading',
            'level': 1 if m.group(2) == '=' else 2,
            'text': m.group(1),
        })

def output_text(self, m):
        text = m.group(0)
        return self.renderer.text(text)

def parse_text(self, m):
        text = m.group(0)
        self.tokens.append({'type': 'text', 'text': text})

def _break_text(text, max_width, break_character):
    words = text.split()
    for word in words:
        if len(word) > max_width:
            replacement = _insert_break(word, max_width, break_character)
            text = text.replace(word, replacement)
    return text

def allow_element(self, el):
        """
        Decide whether an element is configured to be accepted or rejected.

        :param el: an element.
        :return: true to accept the element or false to reject/discard it.
        """
        if el.tag not in self._tag_link_attrs:
            return False
        attr = self._tag_link_attrs[el.tag]
        if isinstance(attr, (list, tuple)):
            for one_attr in attr:
                url = el.get(one_attr)
                if not url:
                    return False
                if not self.allow_embedded_url(el, url):
                    return False
            return True
        else:
            url = el.get(attr)
            if not url:
                return False
            return self.allow_embedded_url(el, url)

def _override_routes(self, rule):
        try:
            routes_to_remove = [r for r in self.url_map._rules if r.rule == rule]
            if routes_to_remove:
                updated_rules = [
                    r.empty()
                    for r in self.url_map._rules
                    if not contains_route(routes_to_remove, r)
                ]
                url_map_keys = [
                    "default_subdomains",
                    "charset",
                    "strict_slashes",
                    "merge_slashes",
                    "redirect_defaults",
                    "converters",
                    "sort_parameters",
                    "sort_key",
                    "encoding_errors",
                    "host_matching",
                ]
                url_map_data = {
                    k: getattr(self.url_map, k)
                    for k in url_map_keys
                    if hasattr(self.url_map, k)
                }
                self.url_map = Map(rules=updated_rules, **url_map_data)

            self.url_map._remap = True
            self.url_map.update()
        except BaseException:
            logger.exception(
                "Could not override routes, if you're trying to specify a route for '/' then it will be ignored..."
            )

def drop_filtered_rows(data_id):
    curr_settings = global_state.get_settings(data_id) or {}
    final_query = build_query(data_id, curr_settings.get("query"))
    curr_history = global_state.get_history(data_id) or []
    curr_history += [
        (
            "# drop filtered rows\n"
            'df = df.query("{}")'.format(final_query.replace("`", ""))
        )
    ]
    global_state.set_history(data_id, curr_history)
    data = run_query(
        handle_predefined(data_id),
        final_query,
        global_state.get_context_variables(data_id),
        ignore_empty=True,
    )
    global_state.set_data(data_id, data)
    global_state.set_dtypes(data_id, build_dtypes_state(data, []))
    curr_predefined = curr_settings.get("predefinedFilters", {})
    global_state.update_settings(
        data_id,
        dict(
            query="",
            columnFilters={},
            outlierFilters={},
            predefinedFilters={
                k: dict_merge(v, {"active": False}) for k, v in curr_predefined.items()
            },
            invertFilter=False,
        ),
    )
    return jsonify(dict(success=True))

def export_html(data_id, return_data):
    def load_file(fpath, encoding="utf-8"):
        return read_file(
            os.path.join(os.path.dirname(__file__), "static/{}".format(fpath)),
            encoding=encoding,
        )

    istok_woff = load_file("fonts/istok_woff64.txt", encoding=None)
    istok_bold_woff = load_file("fonts/istok-bold_woff64.txt", encoding=None)

    font_styles = (
        """
        @font-face {
          font-family: "istok";
          font-weight: 400;
          font-style: normal;
          src: url(data:font/truetype;charset=utf-8;base64,"""
        + istok_woff
        + """) format("woff");
        }

        @font-face {
          font-family: "istok";
          font-weight: 700;
          font-style: normal;
          src: url(data:font/truetype;charset=utf-8;base64,"""
        + istok_bold_woff
        + """) format("woff");
        }
        """
    )

    main_styles = load_file("css/main.css", encoding="utf-8" if PY3 else None).split(
        "\n"
    )
    main_styles = "\n".join(main_styles[28:])
    main_styles = "{}\n{}\n".format(font_styles, main_styles)

    if not PY3:
        main_styles = main_styles.decode("utf-8")

    return_data["results"] = {r[IDX_COL]: r for r in return_data["results"]}

    polyfills_js = load_file("dist/polyfills_bundle.js")
    export_js = load_file("dist/export_bundle.js")

    return send_file(
        base_render_template(
            "dtale/html_export.html",
            data_id,
            main_styles=main_styles,
            polyfills_js=polyfills_js,
            export_js=export_js,
            response=return_data,
        ),
        "dtale_html_export_{}.html".format(json_timestamp(pd.Timestamp("now"))),
        "text/html",
    )

def build_missingno_chart(chart_type, data_id):
    from matplotlib.backends.backend_agg import FigureCanvasAgg as FigureCanvas

    df = global_state.get_data(data_id)
    if chart_type == "matrix":
        date_index = get_str_arg(request, "date_index")
        freq = get_str_arg(request, "freq")
        if date_index:
            figure = msno.matrix(df.set_index(date_index), freq=freq)
        else:
            figure = msno.matrix(df)
    elif chart_type == "bar":
        figure = msno.bar(df)
    elif chart_type == "heatmap":
        figure = msno.heatmap(df)
    elif chart_type == "dendrogram":
        figure = msno.dendrogram(df)

    output = BytesIO()
    FigureCanvas(figure.get_figure()).print_png(output)
    if get_bool_arg(request, "file"):
        fname = "missingno_{}.png".format(chart_type)
        return send_file(output.getvalue(), fname, "image/png")
    return Response(output.getvalue(), mimetype="image/png")

